        string callerRole = "ORGANIZATION")
    {
        eventProducerMock ??= new Mock<IRequestEventProducer>();
        httpClientFactory ??= CreateStubHttpClientFactory(HttpStatusCode.OK, new
        {
            success = true,
            data = new
            {
                id = 1,
                foodTitle = "Fresh Sandwiches",
