            RequestedQuantity = 10,
            Status = "PENDING"
        };
        db.Requests.Add(req);
        await db.SaveChangesAsync();

        // Act
        req.Status = "ACCEPTED";
        await db.SaveChangesAsync();

        // Assert
        var updated = await db.Requests.FirstAsync(r => r.Id == req.Id);
        updated.RequestedQuantity.Should().Be(10);
    }

